import Foundation

/// Boot records Rufus writes for the MS-DOS / FreeDOS entries.
/// Extracted from rufus/src/ms-sys/inc (GPLv3, same project).
enum DosBoot {
    struct Patch { let offset: Int; let bytes: Data }

    /// fat16Head — 11 bytes at 0x0
    static let fat16Head = Data(base64Encoded: "6zyQTVNXSU40LjE=")!

    /// fat16Code — 450 bytes at 0x3e
    static let fat16Code = Data(base64Encoded: "")!

    /// fat32Head — 11 bytes at 0x0
    static let fat32Head = Data(base64Encoded: "61iQTVNXSU40LjE=")!

    /// fat32Code — 918 bytes at 0x52
    static let fat32Code = Data(base64Encoded: "")!

    /// fat32Tail — 528 bytes at 0x3f0
    static let fat32Tail = Data(base64Encoded: "")!

    static func patches(fat32: Bool) -> [Patch] {
        fat32
            ? [Patch(offset: 0x00, bytes: fat32Head),
               Patch(offset: 0x52, bytes: fat32Code),
               Patch(offset: 0x3f0, bytes: fat32Tail)]
            : [Patch(offset: 0x00, bytes: fat16Head),
               Patch(offset: 0x3e, bytes: fat16Code)]
    }
}
